// ── PALETTE
const P = {
  navy:"#1F4E79", steel:"#2E75B6", mid:"#BDD7EE", light:"#D6E4F0",
  bg:"#F2F5FB", card:"#FFFFFF", border:"#DDE5F0", text:"#1A2B3C", muted:"#6B7FA0",
  green:"#2E7D32", greenBg:"#E8F5E9", amber:"#E65100", amberBg:"#FFF3E0",
  red:"#C62828", redBg:"#FFEBEE", grey:"#BDBDBD", greyBg:"#F5F5F5",
  na:"#7B68EE", naBg:"#EDE7F6",
};

const ST_CFG = {
  "Closed":        { bg:P.greenBg, txt:P.green,  dot:"#4CAF50",  bar:"#4CAF50"  },
  "Under Review":  { bg:P.amberBg, txt:P.amber,  dot:"#FF9800",  bar:"#FF9800"  },
  "Not Submitted": { bg:P.redBg,   txt:P.red,    dot:"#F44336",  bar:"#F44336"  },
  "N/A":           { bg:P.naBg,    txt:P.na,     dot:P.na,       bar:P.na       },
};
const stCfg = s => ST_CFG[s] || { bg:P.greyBg, txt:P.muted, dot:P.grey, bar:P.grey };

// ── HELPERS
function pct(a,b){ return b ? Math.round(a/b*100) : 0; }

function getStats(rows){
  const active = rows.filter(r=>r[F.st]!=="N/A");
  const c  = active.filter(r=>r[F.st]==="Closed").length;
  const ur = active.filter(r=>r[F.st]==="Under Review").length;
  const ns = active.filter(r=>r[F.st]==="Not Submitted").length;
  const na = rows.filter(r=>r[F.st]==="N/A").length;
  const rooms = new Set(active.map(r=>r[F.ref])).size;
  return { total:active.length, c, ur, ns, na, rooms, pct:pct(c,active.length) };
}

// ── MICRO COMPONENTS
function Badge({ s }){
  const cfg = stCfg(s);
  return <span style={{display:"inline-flex",alignItems:"center",gap:3,padding:"2px 8px",borderRadius:12,
    fontSize:11,fontWeight:600,background:cfg.bg,color:cfg.txt,whiteSpace:"nowrap"}}>
    <span style={{width:6,height:6,borderRadius:"50%",background:cfg.dot,display:"inline-block"}}/>
    {s}
  </span>;
}

function KPI({ label, value, sub, color=P.navy }){
  return <div style={{background:P.card,border:`1px solid ${P.border}`,borderLeft:`4px solid ${color}`,
    borderRadius:8,padding:"12px 16px",flex:1,minWidth:110}}>
    <div style={{fontSize:10,color:P.muted,textTransform:"uppercase",letterSpacing:1,marginBottom:3}}>{label}</div>
    <div style={{fontSize:26,fontWeight:700,color,lineHeight:1}}>{value}</div>
    {sub && <div style={{fontSize:10,color:P.muted,marginTop:3}}>{sub}</div>}
  </div>;
}

function Bar({ v, color=P.steel }){
  return <div style={{background:"#E4EAF4",borderRadius:4,height:7,overflow:"hidden"}}>
    <div style={{width:`${Math.min(100,v)}%`,height:"100%",background:color,borderRadius:4,transition:"width .4s"}}/>
  </div>;
}

// ── PIE CHART (SVG, interactive)
function PieChart({ data, onFilter, activeFilter }){
  // data = [{label, value, color}]
  const total = data.reduce((s,d)=>s+d.value,0);
  if(!total) return <div style={{textAlign:"center",padding:20,color:P.muted,fontSize:12}}>No data</div>;

  let angle = -Math.PI/2;
  const slices = data.map(d=>{
    const a = (d.value/total)*2*Math.PI;
    const x1 = Math.cos(angle), y1 = Math.sin(angle);
    const x2 = Math.cos(angle+a), y2 = Math.sin(angle+a);
    const large = a > Math.PI ? 1 : 0;
    const path = `M0,0 L${x1},${y1} A1,1,0,${large},1,${x2},${y2} Z`;
    const mid = angle + a/2;
    const lx = Math.cos(mid)*0.65, ly = Math.sin(mid)*0.65;
    angle += a;
    return {...d, path, lx, ly, pct: Math.round(d.value/total*100)};
  });

  return <div style={{display:"flex",alignItems:"center",gap:16,flexWrap:"wrap"}}>
    <svg viewBox="-1.1 -1.1 2.2 2.2" style={{width:130,height:130,flexShrink:0}}>
      {slices.map((s,i)=>{
        const active = activeFilter===s.label;
        return <g key={i} style={{cursor:"pointer"}} onClick={()=>onFilter(active ? null : s.label)}>
          <path d={s.path} fill={s.color} stroke="#fff" strokeWidth={0.04}
            style={{opacity:activeFilter && !active ? 0.35 : 1,
              transform:active?"scale(1.05)":"scale(1)",transformOrigin:"0 0",transition:"all .2s"}}/>
          {s.pct >= 8 && <text x={s.lx} y={s.ly} textAnchor="middle" dominantBaseline="middle"
            fontSize={0.18} fill="#fff" fontWeight="bold">{s.pct}%</text>}
        </g>;
      })}
    </svg>
    <div style={{display:"flex",flexDirection:"column",gap:5}}>
      {slices.map((s,i)=>{
        const active = activeFilter===s.label;
        return <div key={i} onClick={()=>onFilter(active ? null : s.label)}
          style={{display:"flex",alignItems:"center",gap:6,cursor:"pointer",
            opacity:activeFilter && !active ? 0.4 : 1,
            fontWeight:active?700:400,fontSize:11,color:P.text}}>
          <span style={{width:10,height:10,borderRadius:2,background:s.color,flexShrink:0}}/>
          <span>{s.label}</span>
          <span style={{color:P.muted,marginLeft:2}}>{s.value}</span>
        </div>;
      })}
    </div>
  </div>;
}

// ── WIR TABLE
function WIRTable({ rows }){
  if(!rows.length) return <div style={{textAlign:"center",padding:28,color:P.muted,fontSize:13}}>
    No records for current selection.
  </div>;
  return <div style={{overflowX:"auto"}}>
    <table style={{width:"100%",borderCollapse:"collapse",fontSize:11.5}}>
      <thead>
        <tr style={{background:P.navy}}>
          {["Room Ref","Room Name","Bldg","Level","Zone","System","Stage","WIR Ref","Status"].map(h=>
            <th key={h} style={{padding:"7px 9px",textAlign:"left",color:"#fff",fontWeight:600,whiteSpace:"nowrap"}}>{h}</th>
          )}
        </tr>
      </thead>
      <tbody>
        {rows.map((r,i)=><tr key={i} style={{background:i%2===0?"#FAFBFD":P.card,borderBottom:`1px solid ${P.border}`}}>
          <td style={{padding:"6px 9px",fontFamily:"monospace",fontSize:10.5,color:P.steel}}>{r[F.ref]}</td>
          <td style={{padding:"6px 9px",color:P.text}}>{r[F.name]}</td>
          <td style={{padding:"6px 9px",color:P.muted}}>{r[F.bldg]}</td>
          <td style={{padding:"6px 9px",color:P.muted,whiteSpace:"nowrap"}}>{r[F.lvl]}</td>
          <td style={{padding:"6px 9px",color:P.muted}}>{r[F.zone]}</td>
          <td style={{padding:"6px 9px",color:P.text}}>{r[F.sys]}</td>
          <td style={{padding:"6px 9px",color:P.muted,whiteSpace:"nowrap"}}>{r[F.stage]}</td>
          <td style={{padding:"6px 9px",fontFamily:"monospace",fontSize:10.5,color:"#333",whiteSpace:"nowrap"}}>{r[F.wir]}</td>
          <td style={{padding:"6px 9px"}}><Badge s={r[F.st]}/></td>
        </tr>)}
      </tbody>
    </table>
  </div>;
}

// ── SEARCH COMPONENT
function RoomSearch({ allRefs, allData, onSelect, selected, onClear }){
  const [q, setQ] = useState("");
  const matches = useMemo(()=>{
    if(!q.trim()) return [];
    const ql = q.toLowerCase();
    return [...new Set(
      allRefs.filter(ref=>{
        const row = allData.find(r=>r[F.ref]===ref);
        return ref.toLowerCase().includes(ql) || (row&&row[F.name].toLowerCase().includes(ql));
      })
    )].slice(0,20);
  },[q,allRefs,allData]);

  return <div>
    <div style={{position:"relative",marginBottom:8}}>
      <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",fontSize:13,color:P.muted}}>🔍</span>
      <input value={selected||q} onChange={e=>{setQ(e.target.value);if(selected)onClear();}}
        placeholder="Search room ref or name..." onClick={()=>selected&&onClear()}
        style={{width:"100%",padding:"8px 10px 8px 30px",borderRadius:6,border:`1px solid ${P.border}`,
          fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"monospace"}}/>
      {(selected||q) && <button onClick={()=>{setQ("");onClear();}}
        style={{position:"absolute",right:8,top:"50%",transform:"translateY(-50%)",
          background:"none",border:"none",cursor:"pointer",color:P.muted,fontSize:16}}>✕</button>}
    </div>
    {matches.length>0 && !selected && <div style={{border:`1px solid ${P.border}`,borderRadius:6,
      maxHeight:160,overflowY:"auto",background:P.card,position:"relative",zIndex:10,marginBottom:8}}>
      {matches.map(ref=>{
        const row = allData.find(r=>r[F.ref]===ref);
        return <div key={ref} onClick={()=>{onSelect(ref);setQ("");}}
          style={{padding:"6px 10px",fontSize:12,cursor:"pointer",display:"flex",justifyContent:"space-between",
            borderBottom:`1px solid ${P.border}`}}
          onMouseEnter={e=>e.currentTarget.style.background="#EBF3FB"}
          onMouseLeave={e=>e.currentTarget.style.background=""}>
          <span style={{fontFamily:"monospace",color:P.steel}}>{ref}</span>
          <span style={{color:P.muted,fontSize:11}}>{row?.[F.name]}</span>
        </div>;
      })}
    </div>}
  </div>;
}

